  const Fp = new Proxy({}, { get: (o, h) => o[h] || (o[h] = new Proxy([], { get: (a, k) => 'ix' + k })) });
  class RD extends RDate { constructor(...a) { if (a.length) super(...a); else super(refMs); } static now() { return refMs; } }
